            Describe.Lean(DescribeId.Create("vertex-card"), DeclarationHandle.Create("D5/S3/Geometry/OriginalLabelTwoSum/PhysicalHistory.vertex_card"), H("vertex_card"), StatementSource.FromLean(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("SOURCE_ONLY_UNCOMPILED. Induct on the actual History. The seed carrier is Fin 4. The CutTree right summand excludes its two actual terminals from Fin 5; the hub and two rim vertices give three new vertices. finite_carrier justifies the finite Nat.card coproduct identity. No desired count is assumed.\nSource namespace D5.S3.Geometry.OriginalLabelTwoSum.PhysicalHistory. Literal declaration/proof; not elaborated metadata:\ntheorem vertex_card {n : Nat} {A : Type} {g : GraphData A V}\n    (h : History n A g) : Nat.card A = 4 + 3*n := by\n  induction h with\n  | seed f => simp only [Nat.card_eq_fintype_card,Fintype.card_fin]; omega\n  | @attach n A g old i ih =>\n    letI : Finite A := finite_carrier old\n    change Nat.card (A ⊕ {z : Wheel.Label // z ≠ 1 ∧ z ≠ 2}) = _\n    have hright : Nat.card {z : Wheel.Label // z ≠ 1 ∧ z ≠ 2} = 3 := by\n      rw [Nat.card_eq_fintype_card]\n      decide\n    rw [Nat.card_sum,hright,ih]\n    omega"))), DescribeRole.Theorem),
