            Describe.Lean(DescribeId.Create("tree-edge-equiv"), DeclarationHandle.Create("D5/S3/Geometry/OriginalLabelTwoSum/PhysicalHistory.treeEdgeEquiv"), H("treeEdgeEquiv"), StatementSource.FromLean(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("SOURCE_ONLY_UNCOMPILED. Map each retained original label to its actual unordered tree edge. GraphData.labels_injective proves injection and GraphData.tree_edges proves surjection by Sym2 induction. No finite-vertex or chord-injectivity hypothesis is used.\nSource namespace D5.S3.Geometry.OriginalLabelTwoSum.PhysicalHistory. Literal declaration/proof; not elaborated metadata:\ndef treeEdgeEquiv {A : Type*} (g : GraphData A V) :\n    {i // i ∈ g.ground} ≃ {d : Sym2 A // d ∈ g.tree.edgeSet} := by\n  let f : {i // i ∈ g.ground} → {d : Sym2 A // d ∈ g.tree.edgeSet} := fun i =>\n    ⟨g.edge i.1,by\n      have hm : ∀ d : Sym2 A, g.edge i.1 = d → d ∈ g.tree.edgeSet := by\n        apply Sym2.ind\n        intro x y he\n        exact (g.tree_edges x y).mpr ⟨i.1,i.2,he⟩\n      exact hm _ rfl⟩\n  apply Equiv.ofBijective f\n  constructor\n  · intro i j he\n    apply Subtype.ext\n    exact g.labels_injective i.1 i.2 j.1 j.2 (congrArg Subtype.val he)\n  · rintro ⟨d,hd⟩\n    induction d using Sym2.ind with\n    | h x y =>\n      obtain ⟨i,hi,he⟩ := (g.tree_edges x y).mp hd\n      exact ⟨⟨i,hi⟩,Subtype.ext he⟩"))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("tree-edge-card"), DeclarationHandle.Create("D5/S3/Geometry/OriginalLabelTwoSum/PhysicalHistory.tree_edge_card"), H("tree_edge_card"), StatementSource.FromLean(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("SOURCE_ONLY_UNCOMPILED. Count physical tree edges through treeEdgeEquiv and ground_card. No Euler count or assumed tree size is a premise.\nSource namespace D5.S3.Geometry.OriginalLabelTwoSum.PhysicalHistory. Literal declaration/proof; not elaborated metadata:\ntheorem tree_edge_card {n : Nat} {A : Type} {g : GraphData A V}\n    (h : History n A g) :\n    Nat.card {d : Sym2 A // d ∈ g.tree.edgeSet} = 3 + 3*n := by\n  rw [← Nat.card_congr (treeEdgeEquiv g),Nat.card_eq_fintype_card,Fintype.card_coe]\n  exact ground_card h"))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("physical-edge-equiv"), DeclarationHandle.Create("D5/S3/Geometry/OriginalLabelTwoSum/PhysicalHistory.physicalEdgeEquiv"), H("physicalEdgeEquiv"), StatementSource.FromLean(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("SOURCE_ONLY_UNCOMPILED. Consume PhysicalGlue.graph_edgeSet and graph_images_disjoint. Existing Set image equivalences use the proved qL/qR injections; Set.union separates their disjoint physical images. This counts edge sets without counting duplicate chord indices.\nSource namespace D5.S3.Geometry.OriginalLabelTwoSum.PhysicalHistory. Literal declaration/proof; not elaborated metadata:\ndef physicalEdgeEquiv {A B : Type*} (s : PhysicalGlue A B V) :\n    {d : Sym2 s.Carrier // d ∈ s.data.graph.edgeSet} ≃\n      {d : Sym2 A // d ∈ s.leftKept.edgeSet} ⊕\n        {d : Sym2 B // d ∈ s.rightKept.edgeSet} := by\n  classical\n  exact ((Equiv.setCongr s.graph_edgeSet).trans\n    (Equiv.Set.union s.graph_images_disjoint)).trans\n      (Equiv.sumCongr\n        (Equiv.Set.image (Sym2.map s.qL) s.leftKept.edgeSet\n          (Sym2.map.injective s.input.qL_injective)).symm\n        (Equiv.Set.image (Sym2.map s.qR) s.rightKept.edgeSet\n          (Sym2.map.injective s.input.qR_injective)).symm)"))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("graph-edge-card"), DeclarationHandle.Create("D5/S3/Geometry/OriginalLabelTwoSum/PhysicalHistory.graph_edge_card"), H("graph_edge_card"), StatementSource.FromLean(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("SOURCE_ONLY_UNCOMPILED. K4 has six physical edges. deleted_card partitions the old actual edge set into the deleted singleton and its complement; the retained port belongs to the graph by tree_le. The actual W4 graph with its actual interface removed has seven edges. physicalEdgeEquiv gives their disjoint sum, hence increase six. The closed finite Lean decide proof terms have not been executed by a compiler or kernel here.\nSource namespace D5.S3.Geometry.OriginalLabelTwoSum.PhysicalHistory. Literal declaration/proof; not elaborated metadata:\ntheorem graph_edge_card {n : Nat} {A : Type} {g : GraphData A V}\n    (h : History n A g) :\n    Nat.card {d : Sym2 A // d ∈ g.graph.edgeSet} = 6 + 6*n := by\n  induction h with\n  | seed f =>\n    change Nat.card {d : Sym2 (Fin 4) // d ∈ (⊤ : SimpleGraph (Fin 4)).edgeSet} = _\n    rw [Nat.card_eq_fintype_card]\n    decide\n  | @attach n A g old i ih =>\n    letI : Finite A := finite_carrier old\n    let s := step g i\n    have he : g.edge i.e ∈ g.graph.edgeSet := by\n      rw [i.edge]\n      exact g.tree_le ((g.tree_edges i.a i.b).mpr ⟨i.e,i.retained,i.edge⟩)\n    have hold := deleted_card g.graph (g.edge i.e) he\n    have hright : Nat.card {d : Sym2 Wheel.Label //\n        d ∈ (Wheel.wheelGraphData.graph.deleteEdges\n          {Wheel.wheelGraphData.kappa (0 : Fin 4)}).edgeSet} = 7 := by\n      letI : DecidableRel Wheel.wheelGraphData.graph.Adj := by\n        intro x y\n        change Decidable ((x ≠ y ∧ (x = 0 ∨ y = 0)) ∨\n          ∃ j : Fin 4, s(x,y) =\n            s((![(1,2),(2,3),(3,4),(4,1)] j : Wheel.Label × Wheel.Label).1,\n              (![(1,2),(2,3),(3,4),(4,1)] j : Wheel.Label × Wheel.Label).2))\n        infer_instance\n      letI : Fintype {d : Sym2 Wheel.Label //\n          d ∈ (Wheel.wheelGraphData.graph.deleteEdges\n            {Wheel.wheelGraphData.kappa (0 : Fin 4)}).edgeSet} :=\n        SimpleGraph.fintypeEdgeSet _\n      rw [Nat.card_eq_fintype_card]\n      decide\n    have hc := Nat.card_congr (physicalEdgeEquiv s)\n    rw [Nat.card_sum] at hc\n    change Nat.card {d : Sym2 s.Carrier // d ∈ s.data.graph.edgeSet} = _\n    change Nat.card {d : Sym2 s.Carrier // d ∈ s.data.graph.edgeSet} =\n      Nat.card {d : Sym2 A // d ∈ (g.graph.deleteEdges {g.edge i.e}).edgeSet} +\n      Nat.card {d : Sym2 Wheel.Label // d ∈ (Wheel.wheelGraphData.graph.deleteEdges\n        {Wheel.wheelGraphData.kappa (0 : Fin 4)}).edgeSet} at hc\n    rw [hc,hright]\n    omega"))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("row-binding"), DeclarationHandle.Create("D5/S3/Geometry/OriginalLabelTwoSum/PhysicalHistory.RowBinding"), H("RowBinding"), StatementSource.FromLean(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("SOURCE_ONLY_UNCOMPILED. This is the relation PRODUCED by handoff: an equivalence of every chord index, equality of the full ground, and equality of every actual path row. It is not a History/Input field or an assumed supplier.\nSource namespace D5.S3.Geometry.OriginalLabelTwoSum.PhysicalHistory. Literal declaration/proof; not elaborated metadata:\nstructure RowBinding {A : Type*} (g : GraphData A V) (r : Rows V) where\n  index : g.chords ≃ r.chords\n  ground : g.ground = r.ground\n  row : ∀ c : g.chords, g.rows.row c = r.row (index c)"))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("handoff"), DeclarationHandle.Create("D5/S3/Geometry/OriginalLabelTwoSum/PhysicalHistory.handoff"), H("handoff"), StatementSource.FromLean(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("SOURCE_ONLY_UNCOMPILED. Build the existing renameRows/RowHistory.seed recursively. At attachment the previous produced binding establishes retention/freshness on its row model. Use RowHistory.attach and appendWheelRows; compose the actual physical survivor equivalence with the previous index equivalence. step_rows and Wheel.ambient_row prove the two row branches. Every duplicate old index and original right survivor is retained.\nSource namespace D5.S3.Geometry.OriginalLabelTwoSum.PhysicalHistory. Literal declaration/proof; not elaborated metadata:\ndef handoff {n : Nat} {A : Type} {g : GraphData A V} (h : History n A g) :\n    Σ r : Rows V, RowHistory n r × RowBinding g r := by\n  induction h with\n  | seed f =>\n    exact ⟨renameRows f K4.seedGraphData.rows,RowHistory.seed f,{\n      index := Equiv.refl _\n      ground := rfl\n      row := fun c => PhysicalLabels.row K4.seedGraphData f s(0,0) c }⟩\n  | @attach n A g old i ih =>\n    let r := ih.1\n    let b := ih.2.2\n    have he : i.e ∈ r.ground := b.ground ▸ i.retained\n    have hf : Disjoint r.ground (Wheel.Y.image i.labels) := b.ground ▸ i.fresh\n    refine ⟨appendWheelRows r i.e he i.labels i.zero,\n      RowHistory.attach ih.2.1 i.e he i.labels i.zero hf,{\n        index := (PhysicalCertificate.attachment_chords g i.e i.retained i.a i.b\n          i.edge i.labels i.zero i.fresh).trans\n            (Equiv.sumCongr b.index (Equiv.refl _))\n        ground := ?_\n        row := ?_ }⟩\n    · change g.ground.erase i.e ∪ Wheel.Y.image i.labels =\n        r.ground.erase i.e ∪ Wheel.Y.image i.labels\n      rw [b.ground]\n    · intro c\n      cases c with\n      | inl c =>\n        change (step g i).data.rows.row (.inl c) =\n          substitute i.e (Wheel.R.image i.labels) (r.row (b.index c))\n        rw [(step_rows g i).1 c,b.row c]\n      | inr d =>\n        change (step g i).data.rows.row (.inr d) =\n          (Wheel.wheelGraphData.rows.row d.1).image i.labels\n        rw [(PhysicalCertificate.attachment_rows g i.e i.retained i.a i.b\n          i.edge i.labels i.zero i.fresh).2 d,Wheel.ambient_row]"))), DescribeRole.Definition),
